import fs from 'node:fs';
import crypto from 'node:crypto';
import {objects} from './research-flickr-venues-20261107.mjs';
const dir='docs/research/photo-multisource-20261107',cache='.logs/photo-multisource-20261107/sources',read=f=>JSON.parse(fs.readFileSync(f,'utf8')),save=(f,v)=>fs.writeFileSync(f,JSON.stringify(v,null,2)+'\n');
const pairs=[['Hotel Xoai','"Xoai" "Can Tho"'],['Mường Thanh Luxury Cao Bằng','"Muong Thanh" "Cao Bang"'],['Pao’s Sapa Leisure Hotel','"Pao" "Sapa"'],['Seagull Hotel','"Seagull" "Quy Nhon"'],['Lotte Hotel Hanoi','"Lotte" "Hanoi"'],['Mercure Hanoi la Gare','"Mercure" "Hanoi"'],['Angsana Lang Co Vietnam','"Angsana" "Lang Co"'],['Azerai La Residence, Hue','"La Residence" "Hue"'],['Mövenpick Resort Cam Ranh','"Movenpick" "Cam Ranh"'],['Mövenpick Resort Waverly Phu Quoc','"Movenpick" "Phu Quoc"'],['Pullman Phu Quoc Beach Resort','"Pullman" "Phu Quoc"'],['Novotel Phu Quoc Resort','"Novotel" "Phu Quoc"'],['Premier Residences Phu Quoc Emerald Bay Managed by Accor','"Premier Residences" "Phu Quoc"'],['Salinda Resort Phu Quoc Island','"Salinda"'],['Mango Bay Resort','"Mango Bay" "Phu Quoc"'],['Tam Coc Garden','"Tam Coc" "Garden"'],['Wyndham Legend Halong','"Wyndham" "Halong"'],['Legacy Yen Tu Resort & Retreat - MGallery Collection','"Legacy" "Yen Tu"']];
const places=fs.readdirSync('backend/src/main/resources/catalog').filter(f=>f.endsWith('.json')).flatMap(f=>{const d=read('backend/src/main/resources/catalog/'+f);return d.places.map(p=>({...p,dest:d.id}));}),file=dir+'/core-hotel-candidates.json',state=fs.existsSync(file)?read(file):{};
const license={1:'CC BY-NC-SA 2.0',2:'CC BY-NC 2.0',4:'CC BY 2.0',5:'CC BY-SA 2.0',9:'CC0',10:'Public domain'};
for(const [name,query]of pairs){const p=places.find(p=>p.name===name);if(!p||p.photos.length||state[p.id])continue;await new Promise(r=>setTimeout(r,1700));const res=await fetch('https://www.flickr.com/search/?'+new URLSearchParams({text:query,license:'1,2,4,5,9,10'}),{signal:AbortSignal.timeout(22000)});if([403,429].includes(res.status)){console.log('Core searches paused '+res.status);break;}if(!res.ok)continue;const raw=await res.text(),sourceFile=cache+'/flickr-core-'+p.id+'.html';fs.writeFileSync(sourceFile,raw);const candidates=[];
 for(const ph of objects(raw)){if(!license[ph.license])continue;const sizes=Object.values(ph.sizes?.data||{}).map(s=>s.data).filter(s=>s&&Math.min(s.width,s.height)>=350&&Math.max(s.width,s.height)>=640).sort((a,b)=>Math.abs(Math.max(a.width,a.height)-1200)-Math.abs(Math.max(b.width,b.height)-1200));if(!sizes.length)continue;const size=sizes[0],sourceUrl='https://www.flickr.com/photos/'+ph.ownerNsid+'/'+ph.id;candidates.push({id:crypto.createHash('sha256').update(sourceUrl).digest('hex').slice(0,18),provider:'flickr-core',title:ph.title,description:ph.description||'',url:(size.url||size.displayUrl).replace(/^\/\//,'https://'),originalUrl:(size.url||size.displayUrl).replace(/^\/\//,'https://'),sourceUrl,author:ph.realname||ph.username,license:license[ph.license],licenseCode:ph.license,width:size.width,height:size.height,sourceFile,status:'PENDING_VISUAL_AND_BRANCH_REVIEW'});}
 state[p.id]={id:p.id,name:p.name,dest:p.dest,address:p.venue.address,kind:p.venue.kind,query,candidates:candidates.slice(0,12)};save(file,state);console.log(JSON.stringify({name,candidates:candidates.length}));
}
save(dir+'/core-free.json',Object.fromEntries(Object.entries(state).map(([id,p])=>[id,{...p,candidates:p.candidates.filter(c=>!c.license.includes('-NC')).slice(0,4)}])));
save(dir+'/core-preview.json',Object.fromEntries(Object.entries(state).map(([id,p])=>[id,{...p,candidates:p.candidates.filter(c=>c.license.includes('-NC')).slice(0,4)}])));
